import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';

/**
 * 센티넬 (UR)
 * - 기본 효과: 게임 시작 시 보호막 1개 보유 (피격 시 게임오버 대신 보호막 소멸)
 * - 특수 능력: 300점마다 보호막 1개 충전 (최대 3개)
 * - UI: 플레이어 주변 붉은 반투명 방어막 + 머리 위 잔여 횟수
 */
export class SentinelAbility extends BaseAbility {
  private shieldCount = 0;
  private shieldGraphics: Phaser.GameObjects.Graphics | null = null;
  private shieldPulseTween: Phaser.Tweens.Tween | null = null;
  private shieldBadge: Phaser.GameObjects.Text | null = null;

  private static readonly RED       = 0xff2222;
  private static readonly RED_LIGHT = 0xff6666;

  override onCreate(api: GameSceneAPI): void {
    this.shieldCount = 1;
    this.buildShieldVisual(api);
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % 300 === 0) {
      this.shieldCount = Math.min(this.shieldCount + 1, 3);
      this.playShieldChargeEffect(api);
      this.buildShieldVisual(api);
    }
  }

  override onHitPoop(api: GameSceneAPI): boolean {
    if (this.shieldCount > 0) {
      this.shieldCount--;
      this.playShieldBreakEffect(api);
      if (this.shieldCount > 0) {
        // 방어막 파괴 후 300ms 뒤 재생성
        api.scene.time.delayedCall(300, () => this.buildShieldVisual(api));
      } else {
        this.destroyShieldVisual();
      }
      return true;
    }
    return false;
  }

  override onUpdate(api: GameSceneAPI): void {
    if (this.shieldGraphics?.active) {
      this.shieldGraphics.setPosition(api.player.x, api.player.y);
    }
    if (this.shieldBadge?.active) {
      this.shieldBadge.setPosition(api.player.x + 22, api.player.y - 50);
    }
  }

  // ─────────────────────────────────────────────────────────────
  // 방어막 시각 오브젝트 관리
  // ─────────────────────────────────────────────────────────────

  private buildShieldVisual(api: GameSceneAPI): void {
    this.destroyShieldVisual();
    if (this.shieldCount === 0) return;

    const scene = api.scene;
    const g = scene.add.graphics().setDepth(90);
    g.setPosition(api.player.x, api.player.y);
    this.drawShield(g);
    this.shieldGraphics = g;

    // 등장: scale 0 → 1 (Back easing으로 탄성 느낌)
    g.setScale(0);
    scene.tweens.add({
      targets: g,
      scaleX: 1,
      scaleY: 1,
      duration: 220,
      ease: 'Back.easeOut',
      onComplete: () => {
        if (!g.active) return;
        this.shieldPulseTween = scene.tweens.add({
          targets: g,
          scaleX: 1.07,
          scaleY: 1.07,
          alpha: 0.65,
          duration: 1000,
          yoyo: true,
          repeat: -1,
          ease: 'Sine.easeInOut',
        });
      },
    });

    // 잔여 횟수 뱃지 (2개 이상일 때만 표시)
    if (this.shieldCount >= 2) {
      this.shieldBadge = scene.add
        .text(api.player.x + 22, api.player.y - 50, `×${this.shieldCount}`, {
          fontSize: '13px',
          color: '#ff9999',
          stroke: '#000000',
          strokeThickness: 3,
        })
        .setOrigin(0.5)
        .setDepth(200);
    }
  }

  private drawShield(g: Phaser.GameObjects.Graphics): void {
    // 보호막 수에 따라 채움/테두리 투명도 소폭 증가
    const fillAlpha   = 0.13 + (this.shieldCount - 1) * 0.04;
    const strokeAlpha = 0.55 + (this.shieldCount - 1) * 0.12;

    g.clear();
    g.fillStyle(SentinelAbility.RED, fillAlpha);
    g.fillEllipse(0, 0, 74, 98);
    g.lineStyle(2, SentinelAbility.RED_LIGHT, strokeAlpha);
    g.strokeEllipse(0, 0, 74, 98);
  }

  private destroyShieldVisual(): void {
    this.shieldPulseTween?.stop();
    this.shieldPulseTween = null;
    this.shieldGraphics?.destroy();
    this.shieldGraphics = null;
    this.shieldBadge?.destroy();
    this.shieldBadge = null;
  }

  // ─────────────────────────────────────────────────────────────
  // 이펙트
  // ─────────────────────────────────────────────────────────────

  /** 보호막 피격 흡수: 타원 링 확장 + 빨간 파편 비산 */
  private playShieldBreakEffect(api: GameSceneAPI): void {
    const scene = api.scene;
    const cx = api.player.x;
    const cy = api.player.y;

    scene.cameras.main.flash(200, 255, 40, 40, true);

    // 타원 충격파 링 2개 (시간차)
    [{ delay: 0, maxScale: 2.8 }, { delay: 75, maxScale: 2.2 }].forEach(({ delay, maxScale }) => {
      const ring = scene.add.graphics().setDepth(150);
      ring.lineStyle(2.5, SentinelAbility.RED_LIGHT, 0.9);
      ring.strokeEllipse(0, 0, 74, 98);
      ring.setPosition(cx, cy);

      scene.tweens.add({
        targets: ring,
        scaleX: maxScale,
        scaleY: maxScale,
        alpha: 0,
        duration: 400,
        delay,
        ease: 'Quad.easeOut',
        onComplete: () => ring.destroy(),
      });
    });

    // 내부 채움 flash
    const fill = scene.add.graphics().setDepth(149);
    fill.fillStyle(SentinelAbility.RED, 0.28);
    fill.fillEllipse(0, 0, 74, 98);
    fill.setPosition(cx, cy);
    scene.tweens.add({
      targets: fill,
      alpha: 0,
      duration: 180,
      ease: 'Quad.easeOut',
      onComplete: () => fill.destroy(),
    });

    // 빨간 파편 8개
    for (let i = 0; i < 8; i++) {
      const angle = (i / 8) * Math.PI * 2 + Phaser.Math.FloatBetween(-0.25, 0.25);
      const speed = Phaser.Math.FloatBetween(40, 95);
      const w     = Phaser.Math.Between(5, 12);
      const h     = Phaser.Math.Between(2, 5);

      const shard = scene.add.graphics().setDepth(152);
      shard.fillStyle(SentinelAbility.RED, 1);
      shard.fillRect(-w / 2, -h / 2, w, h);
      shard.setPosition(cx, cy);
      shard.setRotation(angle);

      scene.tweens.add({
        targets: shard,
        x: cx + Math.cos(angle) * speed,
        y: cy + Math.sin(angle) * speed,
        alpha: 0,
        rotation: angle + Phaser.Math.FloatBetween(-1, 1),
        duration: Phaser.Math.Between(270, 440),
        ease: 'Quad.easeOut',
        onComplete: () => shard.destroy(),
      });
    }
  }

  /** 보호막 충전: 바깥에서 수렴하는 링 + 상승 파티클 */
  private playShieldChargeEffect(api: GameSceneAPI): void {
    const scene = api.scene;
    const cx = api.player.x;
    const cy = api.player.y;

    // 수렴 링 (크게 시작 → 플레이어 크기로 모임)
    const ring = scene.add.graphics().setDepth(150);
    ring.lineStyle(2, SentinelAbility.RED_LIGHT, 1);
    ring.strokeEllipse(0, 0, 74, 98);
    ring.setPosition(cx, cy);
    ring.setScale(1.9);
    ring.setAlpha(0);

    scene.tweens.add({
      targets: ring,
      scaleX: 1,
      scaleY: 1,
      alpha: 1,
      duration: 210,
      ease: 'Quad.easeIn',
      onComplete: () => {
        scene.tweens.add({
          targets: ring,
          alpha: 0,
          duration: 160,
          onComplete: () => ring.destroy(),
        });
      },
    });

    // 상승 파티클 5개
    for (let i = 0; i < 5; i++) {
      const ox  = Phaser.Math.FloatBetween(-22, 22);
      const dot = scene.add.graphics().setDepth(151);
      dot.fillStyle(SentinelAbility.RED_LIGHT, 1);
      dot.fillCircle(0, 0, Phaser.Math.Between(2, 4));
      dot.setPosition(cx + ox, cy + 18);

      scene.tweens.add({
        targets: dot,
        y: cy - Phaser.Math.Between(28, 56),
        alpha: 0,
        duration: Phaser.Math.Between(340, 530),
        delay: i * 40,
        ease: 'Quad.easeOut',
        onComplete: () => dot.destroy(),
      });
    }
  }
}

