import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';

/**
 * 센티넬 (UR)
 * - 기본 효과: 게임 시작 시 보호막 1개 보유 (피격 시 게임오버 대신 보호막 소멸)
 * - 특수 능력: 300점마다 보호막 1개 충전 (최대 3개), 화면 좌상단에 🛡️ UI 표시
 */
export class SentinelAbility extends BaseAbility {
  private shieldCount = 0;
  private shieldIcons: Phaser.GameObjects.Text[] = [];

  private static readonly CYAN = 0x44ddff;

  override onCreate(api: GameSceneAPI): void {
    this.shieldCount = 1;
    this.updateShieldUI(api);
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % 300 === 0) {
      this.shieldCount = Math.min(this.shieldCount + 1, 3);
      this.updateShieldUI(api);
      this.playShieldChargeEffect(api);
    }
  }

  override onHitPoop(api: GameSceneAPI): boolean {
    if (this.shieldCount > 0) {
      this.shieldCount--;
      this.updateShieldUI(api);
      this.playShieldBreakEffect(api);
      return true;
    }
    return false;
  }

  private updateShieldUI(api: GameSceneAPI): void {
    this.shieldIcons.forEach(t => t.destroy());
    this.shieldIcons = [];
    for (let i = 0; i < this.shieldCount; i++) {
      const icon = api.scene.add
        .text(10 + i * 28, 34, '🛡️', { fontSize: '20px' })
        .setDepth(200);
      this.shieldIcons.push(icon);
    }
  }

  /** 보호막 피격 흡수 이펙트: 충격파 링 + 청색 파편 비산 */
  private playShieldBreakEffect(api: GameSceneAPI): void {
    const scene = api.scene;
    const cx = api.player.x;
    const cy = api.player.y;
    const CYAN = SentinelAbility.CYAN;

    // 카메라 청색 flash
    scene.cameras.main.flash(220, 30, 180, 255, true);

    // ── 1. 충격파 링 2개 (80ms 시간차) ──────────────────────────────
    [{ delay: 0, thickness: 3, maxScale: 3.2 },
     { delay: 80, thickness: 1.5, maxScale: 2.6 }].forEach(({ delay, thickness, maxScale }) => {
      const ring = scene.add.graphics().setDepth(150);
      ring.lineStyle(thickness, CYAN, 1);
      ring.strokeCircle(0, 0, 28);
      ring.setPosition(cx, cy);

      scene.tweens.add({
        targets: ring,
        scaleX: maxScale,
        scaleY: maxScale,
        alpha: 0,
        duration: 420,
        delay,
        ease: 'Quad.easeOut',
        onComplete: () => ring.destroy(),
      });
    });

    // ── 2. 내부 채움 (순간 flash) ─────────────────────────────────────
    const fill = scene.add.graphics().setDepth(149);
    fill.fillStyle(CYAN, 0.25);
    fill.fillCircle(0, 0, 28);
    fill.setPosition(cx, cy);
    scene.tweens.add({
      targets: fill,
      alpha: 0,
      duration: 180,
      ease: 'Quad.easeOut',
      onComplete: () => fill.destroy(),
    });

    // ── 3. 청색 파편 비산 (10개) ─────────────────────────────────────
    const SHARD_COUNT = 10;
    for (let i = 0; i < SHARD_COUNT; i++) {
      const angle  = (i / SHARD_COUNT) * Math.PI * 2 + Phaser.Math.FloatBetween(-0.2, 0.2);
      const speed  = Phaser.Math.FloatBetween(45, 105);
      const tx     = cx + Math.cos(angle) * speed;
      const ty     = cy + Math.sin(angle) * speed;
      const w      = Phaser.Math.Between(5, 12);
      const h      = Phaser.Math.Between(2, 5);

      const shard = scene.add.graphics().setDepth(152);
      shard.fillStyle(CYAN, 1);
      shard.fillRect(-w / 2, -h / 2, w, h);
      shard.setPosition(cx, cy);
      shard.setRotation(angle);

      scene.tweens.add({
        targets: shard,
        x: tx,
        y: ty,
        alpha: 0,
        rotation: angle + Phaser.Math.FloatBetween(-0.8, 0.8),
        duration: Phaser.Math.Between(280, 460),
        ease: 'Quad.easeOut',
        onComplete: () => shard.destroy(),
      });
    }
  }

  /** 보호막 충전 이펙트: 위쪽으로 파티클 상승 */
  private playShieldChargeEffect(api: GameSceneAPI): void {
    const scene = api.scene;
    const cx = api.player.x;
    const cy = api.player.y;
    const CYAN = SentinelAbility.CYAN;

    // 충전 링 (안쪽에서 모여드는 느낌 – scaleX/Y 1.5→0.5)
    const ring = scene.add.graphics().setDepth(150);
    ring.lineStyle(2, CYAN, 1);
    ring.strokeCircle(0, 0, 28);
    ring.setPosition(cx, cy);
    ring.setScale(1.8);
    ring.setAlpha(0);

    scene.tweens.add({
      targets: ring,
      scaleX: 0.8,
      scaleY: 0.8,
      alpha: { from: 0, to: 1 },
      duration: 200,
      ease: 'Quad.easeIn',
      onComplete: () => {
        scene.tweens.add({
          targets: ring,
          alpha: 0,
          duration: 150,
          onComplete: () => ring.destroy(),
        });
      },
    });

    // 상승 파티클 6개
    for (let i = 0; i < 6; i++) {
      const ox   = Phaser.Math.FloatBetween(-22, 22);
      const size = Phaser.Math.Between(3, 7);

      const dot = scene.add.graphics().setDepth(151);
      dot.fillStyle(CYAN, 1);
      dot.fillCircle(0, 0, size / 2);
      dot.setPosition(cx + ox, cy + 20);

      scene.tweens.add({
        targets: dot,
        y: cy - Phaser.Math.Between(30, 60),
        alpha: 0,
        duration: Phaser.Math.Between(350, 550),
        delay: i * 40,
        ease: 'Quad.easeOut',
        onComplete: () => dot.destroy(),
      });
    }
  }
}

