  private drawDroplet(g: Phaser.GameObjects.Graphics): void {
    g.clear();
    // 외부 글로우
    g.fillStyle(SentinelAbility.RED, 0.25);
    g.fillCircle(0, 0, 9);
    // 메인 바디
    g.fillStyle(SentinelAbility.RED, 0.92);
    g.fillCircle(0, 0, 5.5);
    // 상단 반사광 (입체감)
    g.fillStyle(0xffffff, 0.45);
    g.fillCircle(-1.5, -1.8, 2);
  }

