import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';

/**
 * 센티넬 (UR)
 * - 기본 효과: 게임 시작 시 보호막 2개 보유 (피격 시 게임오버 대신 보호막 소멸)
 * - 특수 능력: 300점마다 보호막 1개 충전 (최대 3개)
 * - UI: 붉은 공이 허리 주변을 회오리처럼 공전 + 전기 파지직 이펙트
 */
export class SentinelAbility extends BaseAbility {
  private shieldCount = 0;
  private orbitDroplets: Phaser.GameObjects.Graphics[] = [];
  private orbitAngle = 0;
  private bodySparkTimer = 0; // 몸 주변 스파크 누적 시간

  private static readonly ORBIT_SPEED   = 3.0;  // rad/s
  private static readonly ORBIT_RX      = 26;   // 수평 반지름 px
  private static readonly ORBIT_RY      = 7;    // 수직 반지름 px (납작한 디스크)
  private static readonly ORBIT_WAIST_Y = 8;    // 허리 오프셋 (아래로)
  private static readonly RED           = 0xff2222;
  private static readonly RED_LIGHT     = 0xff6666;

  override onCreate(api: GameSceneAPI): void {
    this.shieldCount = 2;
    this.spawnDroplets(api, 2);
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % 300 === 0 && this.shieldCount < 3) {
      this.shieldCount++;
      this.playShieldChargeEffect(api);
      this.spawnDroplets(api, 1);
    }
  }

  override onHitPoop(api: GameSceneAPI): boolean {
    if (this.shieldCount > 0) {
      this.shieldCount--;
      this.scatterDroplets(api, 1);
      this.playShieldBreakEffect(api);
      // 보호막 흡수 후 0.2초 무적 (연속 피격 방지)
      api.player.setInvincibleBriefly(200);
      return true;
    }
    return false;
  }

  override onUpdate(api: GameSceneAPI): void {
    if (this.orbitDroplets.length === 0) return;

    const delta = api.scene.game.loop.delta / 1000;
    this.orbitAngle += SentinelAbility.ORBIT_SPEED * delta;

    const cx      = api.player.x;
    const cy      = api.player.y + SentinelAbility.ORBIT_WAIST_Y;
    const total   = this.orbitDroplets.length;
    const RX      = SentinelAbility.ORBIT_RX;
    const RY      = SentinelAbility.ORBIT_RY;

    this.orbitDroplets.forEach((drop, i) => {
      if (!drop.active) return;
      const angle = this.orbitAngle + (i / total) * Math.PI * 2;
      const sinA  = Math.sin(angle);

      drop.setPosition(
        cx + Math.cos(angle) * RX,
        cy + sinA * RY
      );

      // 앞쪽(sinA > 0)이면 크고 불투명, 뒤쪽은 작고 반투명
      const t = (sinA + 1) / 2; // 0(뒤) ~ 1(앞)
      drop.setScale(0.55 + 0.55 * t);
      drop.setAlpha(0.35 + 0.65 * t);

      // depth 동적 설정: 앞쪽이면 플레이어 위에, 뒤쪽이면 플레이어 아래에
      drop.setDepth(sinA > 0 ? 101 : 89);

      // 공 주변 전기 파지직 (5% 확률)
      if (Math.random() < 0.05) {
        this.spawnElectricSpark(drop.x, drop.y, sinA > 0 ? 102 : 88, api.scene);
      }
    });

    // 몸 주변 전기 파지직 (100ms마다 1~2회)
    this.bodySparkTimer += api.scene.game.loop.delta;
    if (this.bodySparkTimer >= 100) {
      this.bodySparkTimer = 0;
      const count = Phaser.Math.Between(1, 2);
      for (let k = 0; k < count; k++) {
        const angle  = Phaser.Math.FloatBetween(0, Math.PI * 2);
        const radius = Phaser.Math.FloatBetween(18, 34);
        const bx     = api.player.x + Math.cos(angle) * radius;
        const by     = api.player.y + Math.sin(angle) * (radius * 0.6);
        this.spawnElectricSpark(bx, by, 96, api.scene, 2.5);
      }
    }
  }

  // ─────────────────────────────────────────────────────────────
  // 방울 관리
  // ─────────────────────────────────────────────────────────────

  /** count개 방울을 새로 생성해 orbitDroplets에 추가 */
  private spawnDroplets(api: GameSceneAPI, count: number): void {
    const scene = api.scene;
    for (let i = 0; i < count; i++) {
      const g = scene.add.graphics().setDepth(95);
      this.drawDroplet(g);
      g.setPosition(api.player.x, api.player.y + SentinelAbility.ORBIT_WAIST_Y);
      g.setAlpha(0);
      this.orbitDroplets.push(g);

      scene.tweens.add({
        targets: g,
        alpha: 1,
        scaleX: 1,
        scaleY: 1,
        duration: 350,
        delay: i * 50,
        ease: 'Back.easeOut',
      });
    }
  }

  /** 앞쪽 count개 방울을 궤도에서 이탈시켜 흩어지게 함 */
  private scatterDroplets(api: GameSceneAPI, count: number): void {
    const scene = api.scene;
    const removed = this.orbitDroplets.splice(0, count);
    removed.forEach(drop => {
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const dist  = Phaser.Math.FloatBetween(55, 110);
      scene.tweens.add({
        targets: drop,
        x: drop.x + Math.cos(angle) * dist,
        y: drop.y + Math.sin(angle) * dist,
        alpha: 0,
        scaleX: 0.2,
        scaleY: 0.2,
        duration: Phaser.Math.Between(320, 480),
        ease: 'Quad.easeOut',
        onComplete: () => drop.destroy(),
      });
    });
  }

  /** 전기 파지직: 짧은 지그재그 라인 순간 생성 (thickness: 공 주변=1, 몸 주변=2.5) */
  private spawnElectricSpark(ox: number, oy: number, depth: number, scene: Phaser.Scene, thickness = 1): void {
    const spark = scene.add.graphics().setDepth(depth);

    // 진빨강~주황빨강 교차로 전기 색감
    const color = Math.random() < 0.6 ? 0xff3333 : 0xff7744;
    spark.lineStyle(thickness, color, 1);
    spark.beginPath();

    let px = ox + Phaser.Math.Between(-5, 5);
    let py = oy + Phaser.Math.Between(-5, 5);
    spark.moveTo(px, py);

    const segments = Phaser.Math.Between(2, 4);
    for (let j = 0; j < segments; j++) {
      px += Phaser.Math.Between(-9, 9);
      py += Phaser.Math.Between(-9, 9);
      spark.lineTo(px, py);
    }
    spark.strokePath();

    scene.tweens.add({
      targets: spark,
      alpha: 0,
      duration: Phaser.Math.Between(55, 120),
      onComplete: () => spark.destroy(),
    });
  }

  private drawDroplet(g: Phaser.GameObjects.Graphics): void {
    g.clear();
    // 외부 글로우
    g.fillStyle(SentinelAbility.RED, 0.22);
    g.fillCircle(0, 0, 15);
    // 중간 글로우
    g.fillStyle(SentinelAbility.RED, 0.4);
    g.fillCircle(0, 0, 10);
    // 메인 바디
    g.fillStyle(SentinelAbility.RED, 0.95);
    g.fillCircle(0, 0, 7);
    // 상단 반사광 (입체감)
    g.fillStyle(0xffffff, 0.5);
    g.fillCircle(-2, -2.5, 2.5);
  }

  // ─────────────────────────────────────────────────────────────
  // 이펙트
  // ─────────────────────────────────────────────────────────────

  /** 보호막 피격 흡수: 타원 충격파 링 + 빨간 파편 */
  private playShieldBreakEffect(api: GameSceneAPI): void {
    const scene = api.scene;
    const cx    = api.player.x;
    const cy    = api.player.y;

    scene.cameras.main.flash(200, 255, 40, 40, true);

    // 충격파 링 2개 (시간차)
    [{ delay: 0, maxScale: 2.8 }, { delay: 75, maxScale: 2.2 }].forEach(({ delay, maxScale }) => {
      const ring = scene.add.graphics().setDepth(150);
      ring.lineStyle(2.5, SentinelAbility.RED_LIGHT, 0.9);
      ring.strokeEllipse(0, 0, 74, 98);
      ring.setPosition(cx, cy);
      scene.tweens.add({
        targets: ring,
        scaleX: maxScale,
        scaleY: maxScale,
        alpha: 0,
        duration: 400,
        delay,
        ease: 'Quad.easeOut',
        onComplete: () => ring.destroy(),
      });
    });

    // 내부 flash
    const fill = scene.add.graphics().setDepth(149);
    fill.fillStyle(SentinelAbility.RED, 0.28);
    fill.fillEllipse(0, 0, 74, 98);
    fill.setPosition(cx, cy);
    scene.tweens.add({
      targets: fill,
      alpha: 0,
      duration: 180,
      ease: 'Quad.easeOut',
      onComplete: () => fill.destroy(),
    });

    // 빨간 파편 8개
    for (let i = 0; i < 8; i++) {
      const angle = (i / 8) * Math.PI * 2 + Phaser.Math.FloatBetween(-0.25, 0.25);
      const speed = Phaser.Math.FloatBetween(40, 95);
      const w     = Phaser.Math.Between(5, 12);
      const h     = Phaser.Math.Between(2, 5);

      const shard = scene.add.graphics().setDepth(152);
      shard.fillStyle(SentinelAbility.RED, 1);
      shard.fillRect(-w / 2, -h / 2, w, h);
      shard.setPosition(cx, cy);
      shard.setRotation(angle);

      scene.tweens.add({
        targets: shard,
        x: cx + Math.cos(angle) * speed,
        y: cy + Math.sin(angle) * speed,
        alpha: 0,
        rotation: angle + Phaser.Math.FloatBetween(-1, 1),
        duration: Phaser.Math.Between(270, 440),
        ease: 'Quad.easeOut',
        onComplete: () => shard.destroy(),
      });
    }
  }

  /** 보호막 300점 충전: 수렴 링 + 상승 파티클 */
  private playShieldChargeEffect(api: GameSceneAPI): void {
    const scene = api.scene;
    const cx    = api.player.x;
    const cy    = api.player.y;

    const ring = scene.add.graphics().setDepth(150);
    ring.lineStyle(2, SentinelAbility.RED_LIGHT, 1);
    ring.strokeEllipse(0, 0, 74, 98);
    ring.setPosition(cx, cy);
    ring.setScale(1.9);
    ring.setAlpha(0);

    scene.tweens.add({
      targets: ring,
      scaleX: 1, scaleY: 1, alpha: 1,
      duration: 210, ease: 'Quad.easeIn',
      onComplete: () => {
        scene.tweens.add({
          targets: ring, alpha: 0, duration: 160,
          onComplete: () => ring.destroy(),
        });
      },
    });

    for (let i = 0; i < 5; i++) {
      const ox  = Phaser.Math.FloatBetween(-22, 22);
      const dot = scene.add.graphics().setDepth(151);
      dot.fillStyle(SentinelAbility.RED_LIGHT, 1);
      dot.fillCircle(0, 0, Phaser.Math.Between(2, 4));
      dot.setPosition(cx + ox, cy + 18);
      scene.tweens.add({
        targets: dot,
        y: cy - Phaser.Math.Between(28, 56),
        alpha: 0,
        duration: Phaser.Math.Between(340, 530),
        delay: i * 40,
        ease: 'Quad.easeOut',
        onComplete: () => dot.destroy(),
      });
    }
  }
}

