    // 50ms마다 2~3개 작은 스파크 반복 → 지글지글 효과 (~500ms간)
    scene.time.addEvent({
      delay: 50,
      repeat: 9,
      callback: () => {
        const count = Phaser.Math.Between(2, 3);
        for (let i = 0; i < count; i++) {
